// The parts catalogue (engine/parts/catalog.json, generated by tools/bake.mjs) and the geometry of a placed part in the model frame.
import fs from 'node:fs'; import path from 'node:path'; import { fileURLToPath } from 'node:url';
const DIR = path.dirname(fileURLToPath(import.meta.url));
export const CATALOG = JSON.parse(fs.readFileSync(path.join(DIR, 'parts/catalog.json'), 'utf8'));
const ALIAS = {};   // retired ids the LDraw library renamed (3023 → 3023b): accept the common number
for (const id of Object.keys(CATALOG)) { const m = /^(\d+)[a-c]$/.exec(id); if (m && !CATALOG[m[1]]) ALIAS[m[1]] = id; }
export function part(id) { id = String(id).toLowerCase().replace(/\.dat$/, ''); return CATALOG[id] ?? CATALOG[ALIAS[id]] ?? null; }
export const footprint = (def, rot) => (!def ? [1, 1] : rot % 2 === 0 ? [def.w, def.d] : [def.d, def.w]);
export const PL = 0.4;   // a plate, in studs
/** rotate an offset (x, z) about the vertical axis by rot quarter turns (counter-clockwise seen from above: +x → −z) */
export const turn = (x, z, rot) => [[x, z], [z, -x], [-x, -z], [-z, x]][rot & 3];
/** row-major 3×3 rotation for rot quarter turns, matching `turn` */
export const rotM = (rot) => { const [c, s] = [[1, 0], [0, 1], [-1, 0], [0, -1]][rot & 3]; return [c, 0, s, 0, 1, 0, -s, 0, c]; };
const mulv = (m, v) => [m[0] * v[0] + m[1] * v[1] + m[2] * v[2], m[3] * v[0] + m[4] * v[1] + m[5] * v[2], m[6] * v[0] + m[7] * v[1] + m[8] * v[2]];

/** Everything the checker and the viewer need about one placement, in model units (x, z studs; y studs too, i.e. plates × 0.4). */
export function resolve(p) {
  const def = part(p.id);
  if (p.free) {   // exact transform: corners of the body box → world AABB
    const { p: o, m } = p.free; const b = def.body; let lo = [Infinity, Infinity, Infinity], hi = [-Infinity, -Infinity, -Infinity];
    for (const x of [b[0], b[3]]) for (const y of [b[1], b[4]]) for (const z of [b[2], b[5]]) { const w = mulv(m, [x, y, z]); for (let i = 0; i < 3; i++) { lo[i] = Math.min(lo[i], w[i] + o[i]); hi[i] = Math.max(hi[i], w[i] + o[i]); } }
    return { def, origin: o, m, aabb: [...lo, ...hi], studs: [], female: [], cols: [], free: true };
  }
  const [fw, fd] = footprint(def, p.rot); const cx = p.x + fw / 2, cz = p.z + fd / 2, y0 = p.y;
  const m = rotM(p.rot); const b = def.body; const bc = [(b[0] + b[3]) / 2, def.base ?? b[1], (b[2] + b[5]) / 2];
  const r = mulv(m, bc); const origin = [cx - r[0], y0 * PL - r[1], cz - r[2]];
  const at = (x, z) => { const [a, c] = turn(x, z, p.rot); return [cx + a, cz + c]; };
  return {
    def, origin, m, fw, fd,
    aabb: [p.x, y0 * PL, p.z, p.x + fw, (y0 + def.h) * PL, p.z + fd],
    studs: def.studs.map(([x, z, y]) => [...at(x, z), y0 + y]),
    female: def.female.map(([x, z]) => at(x, z)),
    cols: def.cols.map(([x, z, a, c]) => [...at(x, z), y0 + a, y0 + c]),
  };
}
